INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_cjp-souveti_0','Kolik vět jednoduchých obsahuje souvětí „Pršelo, a proto jsme zůstali doma.“?',ARRAY['čtyři','tři','dvě','jednu']::TEXT[],2,'Jsou to věty „Pršelo“ a „proto jsme zůstali doma“.',1,ARRAY[]::TEXT[],NULL,0,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_1','Co je souvětí?',ARRAY['jedno slovo','věta s jedním podmětem','věta bez přísudku','spojení dvou nebo více vět jednoduchých']::TEXT[],3,'Souvětí má alespoň dvě slovesa v osobním tvaru nebo dvě predikace.',1,ARRAY[]::TEXT[],NULL,1,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_2','Která spojka je slučovací?',ARRAY['protože','ale','aby','a']::TEXT[],3,'Spojka a spojuje věty stejné důležitosti.',1,ARRAY[]::TEXT[],NULL,2,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_3','Která spojka je odporovací?',ARRAY['ale','proto','nebo','a']::TEXT[],0,'Ale vyjadřuje rozpor.',2,ARRAY[]::TEXT[],NULL,3,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_4','Která spojka uvozuje vedlejší větu účelovou?',ARRAY['protože','když','ale','aby']::TEXT[],3,'Aby vyjadřuje účel.',2,ARRAY[]::TEXT[],NULL,4,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_5','Která spojka uvozuje vedlejší větu příčinnou?',ARRAY['aby','protože','když','ale']::TEXT[],1,'Protože vyjadřuje příčinu.',2,ARRAY[]::TEXT[],NULL,5,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_6','Jaký druh vedlejší věty je „Když zazvonilo, děti odešly“?',ARRAY['časová','přívlastková','příčinná','podmínková']::TEXT[],0,'Když zazvonilo = kdy? Časová věta.',3,ARRAY[]::TEXT[],NULL,6,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_7','Jaký druh vedlejší věty je v souvětí „Přišel domů, protože ho bolela hlava“?',ARRAY['příčinná','časová','přípustková','účelová']::TEXT[],0,'Protože = příčina.',3,ARRAY[]::TEXT[],NULL,7,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_8','Jaký druh vedlejší věty je „Kdo se bojí“ v souvětí „Kdo se bojí, nesmí do lesa“?',ARRAY['předmětná','podmětná','příslovečná','přívlastková']::TEXT[],1,'Ptáme se kdo nesmí do lesa? Ten, kdo se bojí.',3,ARRAY[]::TEXT[],NULL,8,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_9','Jaký druh vedlejší věty je v souvětí „Řekl, že přijde zítra“?',ARRAY['přívlastková','podmětná','předmětná','časová']::TEXT[],2,'Řekl co? Že přijde zítra.',4,ARRAY[]::TEXT[],NULL,9,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_10','Jaký druh vedlejší věty je v souvětí „Kniha, kterou čtu, je zajímavá“?',ARRAY['přívlastková','časová','předmětná','podmínková']::TEXT[],0,'Jaká kniha? Kterou čtu.',4,ARRAY[]::TEXT[],NULL,10,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_11','Jaký druh vedlejší věty je v souvětí „Kdyby pršelo, nepůjdeme ven“?',ARRAY['podmínková','časová','příčinná','účelová']::TEXT[],0,'Kdyby = podmínka.',4,ARRAY[]::TEXT[],NULL,11,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_12','Jaký druh vedlejší věty je v souvětí „Ačkoli pršelo, šli jsme ven“?',ARRAY['příčinná','přípustková','podmínková','účelová']::TEXT[],1,'Ačkoli vyjadřuje přípustku, tedy děj navzdory překážce.',5,ARRAY[]::TEXT[],NULL,12,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_13','Jak se nazývá souvětí, jehož věty jsou stejně důležité a jsou spojeny např. spojkami a, ale?',ARRAY['souvětí souřadné','souvětí podřadné','věta jednočlenná','věta dvojčlenná']::TEXT[],0,'V souřadném souvětí jsou věty na sobě nezávislé.',5,ARRAY[]::TEXT[],NULL,13,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_14','Kolik vět obsahuje souvětí „Vím, že přijdeš, ale nevím kdy.“?',ARRAY['čtyři','tři','dvě','pět']::TEXT[],0,'Vím / že přijdeš / ale nevím / kdy.',5,ARRAY[]::TEXT[],NULL,14,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_15','Ve větě ''Přišel, protože pršelo.'' je vedlejší věta:',ARRAY['přívlastková','podmětná','příslovečná příčinná','předmětná']::TEXT[],2,'Protože uvádí příčinu, je příslovečná příčinná.',2,ARRAY[]::TEXT[],NULL,15,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_16','Souvětí je:',ARRAY['věta složená z více vět','věta jednoduchá s přísudkem','věta bez podmětu','věta rozkazovací']::TEXT[],0,'Souvětí tvoří hlavní a vedlejší věty.',2,ARRAY[]::TEXT[],NULL,16,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_17','Ve větě ''Kdo se bojí, nechť jde pryč'' je vedlejší věta:',ARRAY['předmětná','přívlastková','podmětná','příslovečná']::TEXT[],2,'Kdo = podmět vedlejší věty.',3,ARRAY[]::TEXT[],NULL,17,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_18','Spojka ''ačkoli'' uvádí vedlejší větu:',ARRAY['účelovou','důsledkovou','podmínkovou','připustkovou']::TEXT[],3,'Ačkoli vyjadřuje připuštění.',3,ARRAY[]::TEXT[],NULL,18,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_19','Ve větě ''Řekl, že přijde.'' je vedlejší věta:',ARRAY['předmětná','přívlastková','podmětná','příslovečná']::TEXT[],0,'Že přijde doplňuje sloveso řekl.',4,ARRAY[]::TEXT[],NULL,19,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_20','Ve větě ''Dům, který stojí na kopci, je starý.'' je vedlejší věta:',ARRAY['příslovečná místní','přívlastková','předmětná','podmětná']::TEXT[],1,'Který stojí... vytváří přívlastek ke slovu dům.',4,ARRAY[]::TEXT[],NULL,20,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_21','Které souvětí je správně?',ARRAY['Přišel, protože, pršelo.','Přišel protože pršelo.','Přišel, protože pršelo.','Přišel protože, pršelo.']::TEXT[],2,'Čárka před vedlejší větou.',1,ARRAY[]::TEXT[],NULL,21,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_22','Ve větě ''Vím, že přijde.'' je vedlejší věta:',ARRAY['podmětná','příslovečná','předmětná','přívlastková']::TEXT[],2,'Vím co? – že přijde.',2,ARRAY[]::TEXT[],NULL,22,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_23','Spojka ''aby'' uvádí vedlejší větu:',ARRAY['podmínkovou','účelovou','příčinnou','časovou']::TEXT[],1,'Aby = účel.',2,ARRAY[]::TEXT[],NULL,23,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_24','Ve větě ''Když přijde, řekni mi.'' je vedlejší věta:',ARRAY['časová','účelová','příčinná','podmínková']::TEXT[],0,'Když = čas.',3,ARRAY[]::TEXT[],NULL,24,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_25','Spojka ''jestliže'' uvádí vedlejší větu:',ARRAY['podmínkovou','účelovou','přípustkovou','časovou']::TEXT[],0,'Jestliže = podmínka.',3,ARRAY[]::TEXT[],NULL,25,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_26','Ve větě ''Kniha, kterou čtu, je zajímavá.'' je vedlejší věta:',ARRAY['předmětná','příslovečná','přívlastková','podmětná']::TEXT[],2,'Kterou = přívlastek.',4,ARRAY[]::TEXT[],NULL,26,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_27','Vedlejší věta, která vyjadřuje důsledek, je:',ARRAY['přípustková','důsledková','podmínková','účelová']::TEXT[],1,'Takže, proto…',4,ARRAY[]::TEXT[],NULL,27,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_28','Vedlejší věta ''Ať je jakkoli, půjdu.'' je:',ARRAY['časová','důsledková','účelová','přípustková']::TEXT[],3,'Ať je jakkoli = připuštění.',5,ARRAY[]::TEXT[],NULL,28,'c_cjp-souveti',NULL,NOW()),
('q_cjp-souveti_29','V souvětí ''Kdo chce, ať přijde.'' je vedlejší věta:',ARRAY['podmětná','předmětná','přívlastková','příslovečná']::TEXT[],0,'Kdo = podmět.',5,ARRAY[]::TEXT[],NULL,29,'c_cjp-souveti',NULL,NOW()),
('q_cjp-frazeologie_0','Co znamená rčení „lhát jako když tiskne“?',ARRAY['mluvit potichu','tisknout noviny','být zticha','velmi hodně lhát']::TEXT[],3,'Znamená to lhát často a ve velkém.',1,ARRAY[]::TEXT[],NULL,0,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_1','Co znamená rčení „být jako pěst na oko“?',ARRAY['vůbec se k sobě nehodit','prát se','být velmi silný','mít modřinu']::TEXT[],0,'Znamená to, že věci nebo lidé k sobě vůbec nesedí.',1,ARRAY[]::TEXT[],NULL,1,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_2','Co znamená rčení „mít máslo na hlavě“?',ARRAY['mít na svědomí nějakou vinu','být štědrý','být tlustý','vařit']::TEXT[],0,'Kdo má máslo na hlavě, není bez viny.',1,ARRAY[]::TEXT[],NULL,2,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_3','Dokonči přísloví: Řemeslo má …',ARRAY['tvrdý chleba','pevné stěny','zlaté dno','stříbrné dno']::TEXT[],2,'Řemeslo má zlaté dno.',2,ARRAY[]::TEXT[],NULL,3,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_4','Dokonči přísloví: Kdo jinému jámu kopá, …',ARRAY['dostane lopatu','je dobrý zahradník','bude bohatý','sám do ní padá']::TEXT[],3,'Kdo jinému jámu kopá, sám do ní padá.',2,ARRAY[]::TEXT[],NULL,4,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_5','Dokonči přísloví: Ráno je moudřejší …',ARRAY['noci','léta','večera','oběda']::TEXT[],2,'Ráno je moudřejší večera.',2,ARRAY[]::TEXT[],NULL,5,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_6','Co znamená rčení „hodit flintu do žita“?',ARRAY['vystřelit','zasít obilí','vzdát se','ztratit zbraň']::TEXT[],2,'Znamená to vzdát se dřív, než je to nutné.',3,ARRAY[]::TEXT[],NULL,6,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_7','Co znamená rčení „kupovat zajíce v pytli“?',ARRAY['lovit','nakupovat zdarma','být chytrý','koupit něco, co dopředu neznám']::TEXT[],3,'Kupuje se věc bez možnosti ji předem prohlédnout.',3,ARRAY[]::TEXT[],NULL,7,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_8','Co znamená rčení „chodit kolem horké kaše“?',ARRAY['vařit','spěchat','vyhýbat se podstatě věci','být hladový']::TEXT[],2,'Kdo chodí kolem horké kaše, nemluví přímo.',3,ARRAY[]::TEXT[],NULL,8,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_9','Co znamená rčení „vzít nohy na ramena“?',ARRAY['rychle utéct','být unavený','nést zavazadlo','být zraněný']::TEXT[],0,'Znamená to rychle uprchnout.',4,ARRAY[]::TEXT[],NULL,9,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_10','Co znamená rčení „strkat hlavu do písku“?',ARRAY['být smutný','hledat poklad','nechtít vidět problém','stavět hrad']::TEXT[],2,'Jako pštros: problém neřeší, jen ho ignoruje.',4,ARRAY[]::TEXT[],NULL,10,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_11','Dokonči přísloví: Když se dva perou, …',ARRAY['třetí vítězí','čtvrtý přijde','třetí pláče','třetí se směje']::TEXT[],3,'Když se dva perou, třetí se směje.',4,ARRAY[]::TEXT[],NULL,11,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_12','Co znamená rčení „dělat z komára velblouda“?',ARRAY['chovat zvířata','cestovat','zveličovat','zmenšovat']::TEXT[],2,'Maličkost vypadá jako velký problém.',5,ARRAY[]::TEXT[],NULL,12,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_13','Co znamená přísloví „Pro dobrotu na žebrotu“?',ARRAY['dobré jídlo je drahé','dobrota se vždy vyplatí','kdo žebrá, hodně získá','laskavý člověk bývá často zneužit']::TEXT[],3,'Kdo je moc dobrý, může skončit chudý.',5,ARRAY[]::TEXT[],NULL,13,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_14','Co znamená rčení „spadl mi kámen ze srdce“?',ARRAY['rozzlobil jsem se','lekl jsem se','velmi se mi ulevilo','zranil jsem se']::TEXT[],2,'Vyjadřuje velkou úlevu.',5,ARRAY[]::TEXT[],NULL,14,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_15','Co znamená rčení ''mít zlaté ručičky''?',ARRAY['být bohatý','být lakomý','být líný','být šikovný']::TEXT[],3,'Zlaté ručičky = šikovnost v rukou.',1,ARRAY[]::TEXT[],NULL,15,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_16','Co znamená přísloví ''Co se v mládí naučíš, na stáří umíš.''?',ARRAY['starým se nedá věřit','vzdělání z mládí vydrží','mladí jsou líní','stáří je moudré']::TEXT[],1,'Naučené v mládí zůstává.',1,ARRAY[]::TEXT[],NULL,16,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_17','Co znamená rčení ''házet perly sviním''?',ARRAY['hodit něco do vody','chovat prasata','plýtvat jídlem','dávat cenné věci tomu, kdo je neocení']::TEXT[],3,'Perly sviním = neocenění dobra.',2,ARRAY[]::TEXT[],NULL,17,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_18','Co znamená rčení ''mít ruku v ohni''?',ARRAY['být si něčím naprosto jistý','pracovat u ohně','být nervózní','být zraněný']::TEXT[],0,'Ručit za někoho nebo něco.',2,ARRAY[]::TEXT[],NULL,18,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_19','Co znamená rčení ''zlatý střed''?',ARRAY['nejvyšší bod','vyvážené řešení','zlato ve středu','nejdražší věc']::TEXT[],1,'Zlatý střed = rozumná rovnováha.',3,ARRAY[]::TEXT[],NULL,19,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_20','Co znamená rčení ''nechat své ruce volné''?',ARRAY['nechat někoho jednat bez zásahu','držet se zpátky','nic nedělat','mít zdravé ruce']::TEXT[],0,'Volné ruce = svoboda jednání.',3,ARRAY[]::TEXT[],NULL,20,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_21','Co znamená rčení ''mít srdce na dlani''?',ARRAY['být zamilovaný','být zlý','mít bolavé srdce','být upřímný a otevřený']::TEXT[],3,'Upřímnost.',4,ARRAY[]::TEXT[],NULL,21,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_22','Co znamená rčení ''dát si na čas''?',ARRAY['nespěchat','přestat','odejít','spěchat']::TEXT[],0,'Nespěchat.',4,ARRAY[]::TEXT[],NULL,22,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-frazeologie_23','Co znamená rčení ''mít v hlavě ptačí mozek''?',ARRAY['mít rád ptáky','zpívat','být hloupý, nepozorný','být chytrý']::TEXT[],2,'Hloupost.',5,ARRAY[]::TEXT[],NULL,23,'c_cjp-frazeologie',NULL,NOW()),
('q_cjp-velka-pismena_0','Která věta je správně?',ARRAY['moje sestra bydlí v brně.','Moje sestra bydlí v Brně.','Moje Sestra bydlí v Brně.','Moje sestra bydlí v brně.']::TEXT[],1,'Věta začíná velkým písmenem a Brno je vlastní jméno.',1,ARRAY[]::TEXT[],NULL,0,'c_cjp-velka-pismena',NULL,NOW()),
